// smoke.spec.js — tool-specific checks for Large CSV Viewer and Search.
// Fixtures are fictional and generated by tests/make-fixtures.js (sample-orders.csv, sample-semicolon.csv).
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const ORDERS = fs.readFileSync(fixture('sample-orders.csv'), 'utf8');
const ORDER_LINES = ORDERS.trim().split('\n').slice(1).map((l) => l.split(','));

// Simulates a real drag-and-drop of a file onto the drop zone.
async function dropFile(page, name, content, type = 'text/csv') {
  return dropFiles(page, [{ name, content, type }]);
}

async function dropFiles(page, files) {
  const dt = await page.evaluateHandle((files) => {
    const d = new DataTransfer();
    for (const f of files) d.items.add(new File([f.content], f.name, { type: f.type }));
    return d;
  }, files);
  await page.dispatchEvent('#dropzone', 'dragenter', { dataTransfer: dt });
  await page.dispatchEvent('#dropzone', 'drop', { dataTransfer: dt });
}

async function openOrders(page) {
  await page.setInputFiles('#file-input', fixture('sample-orders.csv'));
  await expect(page.locator('#row-count')).toHaveText('50,000 rows');
}

// Values of one column for the rows currently drawn, in screen order.
async function visibleColumn(page, ci) {
  return page.evaluate((ci) => {
    const rows = [...document.querySelectorAll('#grid-body .grid__row:not([hidden])')];
    rows.sort((a, b) => Number(a.dataset.pos) - Number(b.dataset.pos));
    return rows.map((r) => r.querySelectorAll('.grid__cell')[ci].textContent);
  }, ci);
}

test.describe('Large CSV Viewer and Search', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('./');
  });

  test('dropping sample-orders.csv shows a table with the header row and a row count', async ({ page }) => {
    await dropFile(page, 'sample-orders.csv', ORDERS);
    await expect(page.locator('#row-count')).toHaveText('50,000 rows');
    await expect(page.locator('#stats')).toContainText('7 columns');
    await expect(page.locator('#stats')).toContainText('comma-separated');
    const headers = await page.locator('#grid-head .hcell__name').allTextContents();
    expect(headers).toEqual(['order_id', 'date', 'customer', 'city', 'item', 'qty', 'total']);
    await expect(page.locator('#has-header')).toBeChecked();
    await expect(page.locator('#dropzone')).toBeHidden();
    await expect(page.locator('#file-name')).toHaveText('sample-orders.csv');
    const first = await visibleColumn(page, 0);
    expect(first[0]).toBe('NP-100000');
    // Quoted fields with commas are kept in one cell.
    expect(ORDERS).toContain('"Rope, 10 m coil"');
    const items = await visibleColumn(page, 4);
    expect(items.some((v) => v.includes(','))).toBe(true);
  });

  test('clicking a column header sorts the rows and clicking again reverses the order', async ({ page }) => {
    await openOrders(page);
    const totals = ORDER_LINES.map((l) => l[l.length - 1]).filter(Boolean).map(Number);
    const max = Math.max(...totals);
    const min = Math.min(...totals);
    const header = page.locator('#grid-head .hcell__sort', { hasText: 'total' });

    await header.click();
    await expect(page.locator('#grid-head [role=columnheader]').nth(7)).toHaveAttribute('aria-sort', 'ascending');
    let vals = (await visibleColumn(page, 6)).slice(0, 10).map(Number);
    expect(vals[0]).toBe(min);
    expect([...vals].sort((a, b) => a - b)).toEqual(vals); // numeric, not text, order

    await header.click();
    await expect(page.locator('#grid-head [role=columnheader]').nth(7)).toHaveAttribute('aria-sort', 'descending');
    vals = (await visibleColumn(page, 6)).slice(0, 10).map(Number);
    expect(vals[0]).toBe(max);
    expect([...vals].sort((a, b) => b - a)).toEqual(vals);

    // ISO dates sort chronologically.
    await page.locator('#grid-head .hcell__sort', { hasText: 'date' }).click();
    const dates = (await visibleColumn(page, 1)).slice(0, 10);
    expect(dates[0]).toBe(ORDER_LINES.map((l) => l[1]).sort()[0]);
    expect([...dates].sort()).toEqual(dates);
  });

  test('typing in the search box filters to matching rows and shows the match count', async ({ page }) => {
    await openOrders(page);
    const expected = ORDER_LINES.filter((l) => l.join(',').toLowerCase().includes('renée')).length;
    expect(expected).toBeGreaterThan(0);
    await page.keyboard.press('/');
    await expect(page.locator('#search')).toBeFocused();
    await page.keyboard.type('Renée');
    await expect(page.locator('#match-count')).toHaveText(`${expected} of 50,000 rows match`);
    await expect(page.locator('#grid-body .grid__row:not([hidden])')).toHaveCount(expected);
    await expect(page.locator('#grid-body mark').first()).toHaveText('Renée');

    // The filtered view downloads as a real CSV file.
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download-csv')]);
    expect(download.suggestedFilename()).toBe('sample-orders-view.csv');
    const text = fs.readFileSync(await download.path(), 'utf8').replace(/^\uFEFF/, '');
    const lines = text.trim().split(/\r\n/);
    expect(lines[0]).toBe('order_id,date,customer,city,item,qty,total');
    expect(lines.length).toBe(expected + 1);
    expect(lines.slice(1).every((l) => l.includes('Renée'))).toBe(true);

    // Escape clears the search.
    await page.locator('#search').press('Escape');
    await expect(page.locator('#match-count')).toHaveText('Showing all rows');
  });

  test('per-column filters, column details and column hiding work', async ({ page }) => {
    await openOrders(page);
    const emptyCities = ORDER_LINES.filter((l) => l[3] === '').length;
    await page.click('#add-filter');
    await page.selectOption('.filter__col', { label: 'city' });
    await page.selectOption('.filter__op', 'empty');
    await expect(page.locator('#match-count')).toHaveText(`${emptyCities.toLocaleString('en-US')} of 50,000 rows match`);
    await page.selectOption('.filter__op', 'equals');
    await page.fill('.filter__value', 'port alder');
    const portAlder = ORDER_LINES.filter((l) => l[3] === 'Port Alder').length;
    await expect(page.locator('#match-count')).toHaveText(`${portAlder.toLocaleString('en-US')} of 50,000 rows match`);
    await page.click('[aria-label="Remove filter 1"]');
    await expect(page.locator('#match-count')).toHaveText('Showing all rows');

    await page.click('[aria-label="Details for column city"]');
    const pop = page.locator('#col-pop');
    await expect(pop).toBeVisible();
    await expect(pop).toContainText(`Empty cells${emptyCities}`);
    await expect(pop).toContainText('Distinct values8');
    await pop.getByRole('button', { name: 'Hide column' }).click();
    await expect(page.locator('#grid-head .hcell__name')).toHaveCount(6);
    await expect(page.locator('#stats')).toContainText('1 hidden');
    await page.click('#toggle-cols');
    await page.click('#col-panel >> text=Show all');
    await expect(page.locator('#grid-head .hcell__name')).toHaveCount(7);
  });

  test('the delimiter is detected automatically for a semicolon file', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample-semicolon.csv'));
    await expect(page.locator('#row-count')).toHaveText('40 rows');
    await expect(page.locator('#stats')).toContainText('4 columns');
    await expect(page.locator('#stats')).toContainText('semicolon-separated');
    await expect(page.locator('#delimiter option').first()).toHaveText('Auto (semicolon)');
    expect(await page.locator('#grid-head .hcell__name').allTextContents()).toEqual(['sku', 'product', 'stock', 'price']);

    // Decimal comma toggle makes "129,00" sort as a number.
    await page.check('#decimal-comma');
    await page.locator('#grid-head .hcell__sort', { hasText: 'price' }).click();
    await page.locator('#grid-head .hcell__sort', { hasText: 'price' }).click();
    expect((await visibleColumn(page, 3))[0]).toBe('129,00');

    // Overriding the delimiter re-parses the file.
    await page.selectOption('#delimiter', '|');
    await expect(page.locator('#stats')).toContainText('1 column ·');
    await expect(page.locator('#stats')).toContainText('pipe-separated');
    await page.selectOption('#delimiter', '');
    await expect(page.locator('#stats')).toContainText('4 columns');
  });

  test('scrolling a 100,000 row sample stays responsive because rows are virtualised', async ({ page }) => {
    const lines = ['id,name,value,flag'];
    for (let i = 1; i <= 100000; i++) lines.push(`${i},Item ${i},${(i * 37) % 1000},${i % 2 ? 'yes' : 'no'}`);
    await page.setInputFiles('#file-input', { name: 'hundred-k.csv', mimeType: 'text/csv', buffer: Buffer.from(lines.join('\n')) });
    await expect(page.locator('#row-count')).toHaveText('100,000 rows');

    const drawn = await page.locator('#grid-body .grid__row').count();
    expect(drawn).toBeLessThanOrEqual(100); // a small pool, not 100,000 elements

    const timing = await page.evaluate(async () => {
      const grid = document.getElementById('grid');
      const frame = () => new Promise((r) => requestAnimationFrame(() => r()));
      const times = [];
      for (let k = 1; k <= 30; k++) {
        const t0 = performance.now();
        grid.scrollTop = (grid.scrollHeight - grid.clientHeight) * (k / 30);
        await frame();
        await frame();
        times.push(performance.now() - t0);
      }
      return { avg: times.reduce((a, b) => a + b, 0) / times.length, max: Math.max(...times) };
    });
    expect(timing.avg).toBeLessThan(80);
    expect(await page.locator('#grid-body .grid__row').count()).toBe(drawn);
    await expect(page.locator('#grid-body .grid__row:not([hidden]) .grid__rn', { hasText: /^100000$/ })).toBeVisible();
    const lastIds = await visibleColumn(page, 0);
    expect(lastIds).toContain('100000');

    // Keyboard navigation moves the selection and Ctrl+C copies the cell.
    await page.context().grantPermissions(['clipboard-read', 'clipboard-write']);
    await page.evaluate(() => { document.getElementById('grid').scrollTop = 0; });
    await page.locator('#grid-body .grid__row[data-pos="0"] .grid__cell').nth(1).click();
    await expect(page.locator('#drawer')).toBeVisible();
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    await expect(page.locator('#grid-body [aria-selected=true]')).toHaveText('Item 3');
    await expect(page.locator('#drawer-title')).toHaveText('Row 3');
    await page.keyboard.press('ControlOrMeta+c');
    await expect.poll(() => page.evaluate(() => navigator.clipboard.readText())).toBe('Item 3');
  });

  test('works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await openOrders(page);
    const widths = await page.evaluate(() => ({
      doc: document.documentElement.scrollWidth,
      win: window.innerWidth,
      gridScroll: document.getElementById('grid').scrollWidth,
      gridClient: document.getElementById('grid').clientWidth,
    }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win);
    expect(widths.gridScroll).toBeGreaterThan(widths.gridClient); // wide tables scroll inside the grid
    await expect(page.locator('#search')).toBeVisible();
    await expect(page.locator('#download-csv')).toBeVisible();
    await page.locator('#grid-body .grid__row[data-pos="0"] .grid__cell').first().click();
    const drawer = page.locator('#drawer');
    await expect(drawer).toBeVisible();
    await expect(drawer.locator('dt').nth(2)).toHaveText('customer');
    await expect(drawer.locator('dd').nth(0)).toHaveText('NP-100000');
    const box = await drawer.boundingBox();
    expect(box.width).toBeLessThanOrEqual(390);
    await page.keyboard.press('Escape');
    await expect(drawer).toBeHidden();
    expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(390);
  });

  test('rejects wrong file types, also when mixed with a CSV', async ({ page }) => {
    await dropFiles(page, [
      { name: 'sample.png', content: 'not really an image', type: 'image/png' },
      { name: 'sample-semicolon.csv', content: fs.readFileSync(fixture('sample-semicolon.csv'), 'utf8'), type: 'text/csv' },
    ]);
    await expect(page.locator('#results .alert--error')).toContainText('sample.png');
    await expect(page.locator('#row-count')).toHaveText('40 rows');

    await page.goto('./');
    await page.setInputFiles('#file-input', fixture('sample.pdf'));
    await expect(page.locator('#results .alert--error')).toContainText('not CSV');
    await expect(page.locator('#dropzone')).toBeVisible();
  });

  test('explains binary files and handles BOM, ragged rows, quoted line breaks and Windows-1252', async ({ page }) => {
    await page.setInputFiles('#file-input', { name: 'broken.csv', mimeType: 'text/csv', buffer: Buffer.from([0x41, 0x2c, 0x42, 0x0a, 0x00, 0x01, 0x02, 0x03, 0x00, 0x00]) });
    await expect(page.locator('#results .alert--error')).toContainText('binary');

    const text = '\uFEFFname,note,score\nAlpha,"two\nlines",3\nBeta,short\nGamma,x,5,extra\n';
    await page.setInputFiles('#file-input', { name: 'odd.csv', mimeType: 'text/csv', buffer: Buffer.from(text, 'utf8') });
    await expect(page.locator('#row-count')).toHaveText('3 rows');
    expect(await page.locator('#grid-head .hcell__name').allTextContents()).toEqual(['name', 'note', 'score', 'Column 4']);
    await page.locator('#grid-body .grid__row[data-pos="0"] .grid__cell').nth(1).click();
    await expect(page.locator('#drawer dd').nth(1)).toHaveText('two\nlines');

    // "café" encoded as Windows-1252 (0xE9) is not valid UTF-8 and falls back.
    const latin = Buffer.concat([Buffer.from('drink,price\ncaf'), Buffer.from([0xe9]), Buffer.from(',3.50\n')]);
    await page.setInputFiles('#file-input', { name: 'latin.csv', mimeType: 'text/csv', buffer: latin });
    await expect(page.locator('#stats')).toContainText('Windows-1252');
    expect((await visibleColumn(page, 0))[0]).toBe('café');
  });

  test('the header toggle treats the first row as data', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample-semicolon.csv'));
    await expect(page.locator('#row-count')).toHaveText('40 rows');
    await page.uncheck('#has-header');
    await expect(page.locator('#row-count')).toHaveText('41 rows');
    expect((await page.locator('#grid-head .hcell__name').allTextContents())[0]).toBe('Column 1');
    expect((await visibleColumn(page, 0))[0]).toBe('sku');
  });

  test('a file above the size limit can be previewed, and the preview stays a preview', async ({ page }) => {
    const lines = ['id,value'];
    for (let i = 1; i <= 120000; i++) lines.push(`${i},${i % 7}`);
    const buffer = Buffer.from(lines.join('\n'));
    // Lower the 300 MB threshold so a small fixture takes the big-file path.
    await page.evaluate(() => import('./app.js').then((m) => m.setBigFileLimit(1024)));
    await page.setInputFiles('#file-input', { name: 'big.csv', mimeType: 'text/csv', buffer });
    const box = page.locator('.big-file');
    await expect(box).toContainText('big.csv');
    await box.getByRole('button', { name: 'Preview first 100,000 rows' }).click();
    await expect(page.locator('#row-count')).toHaveText('100,000 rows (preview)');
    await expect(page.locator('#stats')).toContainText('first 100,000 rows only');
    await page.evaluate(() => { const g = document.getElementById('grid'); g.scrollTop = g.scrollHeight; });
    await expect(page.locator('#grid-body .grid__row:not([hidden]) .grid__rn', { hasText: /^100000$/ })).toBeVisible();
    expect((await visibleColumn(page, 0)).includes('100001')).toBe(false);

    // Re-parsing (delimiter override) must not silently load the whole file.
    await page.selectOption('#delimiter', ',');
    await expect(page.locator('#row-count')).toHaveText('100,000 rows (preview)');
    await expect(page.locator('#stats')).toContainText('first 100,000 rows only');

    // Loading everything is still possible and is not marked as a preview.
    await page.setInputFiles('#file-input', { name: 'big.csv', mimeType: 'text/csv', buffer });
    await page.locator('.big-file').getByRole('button', { name: 'Load the whole file' }).click();
    await expect(page.locator('#row-count')).toHaveText('120,000 rows');
    await expect(page.locator('#stats')).not.toContainText('preview');
  });

  test('__demo shows a finished, sorted and searched view', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#row-count')).toHaveText('50,000 rows');
    await expect(page.locator('#match-count')).toContainText('of 50,000 rows match');
    await expect(page.locator('#grid-body [aria-selected=true]')).toHaveCount(1);
  });
});
